package com.example.rokidgeminisecretary;
import android.content.Context;import org.json.*;import java.io.*;import java.text.Normalizer;
/** User-created encrypted leg plans. No bundled addresses or timetables. */
public final class SavedNavigationRoutes {
 static final String STORE="saved-navigation";
 public static String mode(JSONObject leg){String mode=leg.optString("mode");return mode.equals("rail")||mode.equals("bus")?"transit":mode;}
 public static String label(String mode){return mode.equals("rail")?"電車":mode.equals("bus")?"バス":mode.equals("bicycling")?"自転車":"徒歩";}
 public static JSONObject point(String name)throws Exception{return new JSONObject().put("name",name);}
 public static JSONObject leg(String from,String to,String mode)throws Exception{return new JSONObject().put("from",point(from)).put("to",point(to)).put("mode",mode).put("board","").put("alight","").put("line","").put("entry","");}
 public static JSONObject draft(String name,boolean returnTrip)throws Exception{JSONArray legs=new JSONArray();if(returnTrip)legs.put(leg("出発地","駅B","walking")).put(leg("駅B","駅A","rail")).put(leg("駅A","目的地","bicycling"));else legs.put(leg("出発地","駅A","bicycling")).put(leg("駅A","駅B","rail")).put(leg("駅B","降車地","bus")).put(leg("降車地","目的地","walking"));return new JSONObject().put("id",java.util.UUID.randomUUID().toString()).put("revision",0).put("name",name).put("legs",legs);}
 public static boolean located(JSONObject point){return point!=null&&!point.optString("name").trim().isEmpty()&&point.has("latitude")&&point.has("longitude")&&Double.isFinite(point.optDouble("latitude"))&&Double.isFinite(point.optDouble("longitude"))&&Math.abs(point.optDouble("latitude"))<=90&&Math.abs(point.optDouble("longitude"))<=180;}
 public static boolean ready(JSONObject leg){return leg!=null&&located(leg.optJSONObject("from"))&&located(leg.optJSONObject("to"))&&(!mode(leg).equals("transit")||!leg.optString("board").trim().isEmpty()&&!leg.optString("alight").trim().isEmpty());}
 public static JSONObject validate(JSONObject input)throws Exception{JSONObject out=new JSONObject(input.toString());if(!out.optString("id").matches("[a-f0-9-]{36}")||out.optString("name").trim().isEmpty()||out.optString("name").length()>80)throw new IOException("ルート名を確認してください");if(!out.optString("shortcut","none").matches("none|outbound|return"))throw new IOException("ショートカットを確認してください");JSONArray legs=out.getJSONArray("legs");if(legs.length()<1||legs.length()>12)throw new IOException("区間は1〜12件です");for(int i=0;i<legs.length();i++){JSONObject l=legs.getJSONObject(i);NavigationCommutePolicy.validate(l);if(!l.optString("landmarkId").isEmpty()&&!l.optString("landmarkId").matches("[a-f0-9-]{36}"))throw new IOException("関連メモを選び直してください");if(!l.optString("mode").matches("walking|bicycling|rail|bus"))throw new IOException("移動手段を確認してください");for(String k:new String[]{"board","alight","line","entry"})if(l.optString(k).length()>160)throw new IOException("指定が長すぎます");for(String k:new String[]{"from","to"}){JSONObject p=l.getJSONObject(k);if(p.optString("name").length()>300||p.has("latitude")!=p.has("longitude")||p.has("latitude")&&!located(p))throw new IOException("地点を候補から選び直してください");}}if(out.toString().length()>24000)throw new IOException("ルートが大きすぎます");return out;}
 public static synchronized JSONArray list(Context c)throws Exception{android.util.AtomicFile file=ConversationWorkspace.file(c,STORE);if(!file.getBaseFile().exists()&&!new File(file.getBaseFile()+".bak").exists())return new JSONArray();JSONObject data=ConversationWorkspace.read(c,STORE);if(data.toString().length()>480000)throw new IOException("保存ルートを確認してください");return data.getJSONArray("items");}
 public static synchronized JSONObject get(Context c,String id)throws Exception{JSONArray rows=list(c);for(int i=0;i<rows.length();i++)if(id.equals(rows.getJSONObject(i).optString("id")))return new JSONObject(rows.getJSONObject(i).toString());throw new IOException("ルートが削除されています");}
 public static synchronized JSONObject save(Context c,JSONObject input)throws Exception{JSONObject row=validate(input);JSONArray rows=list(c),next=new JSONArray();boolean found=false;for(int i=0;i<rows.length();i++){JSONObject old=rows.getJSONObject(i);if(old.getString("id").equals(row.getString("id"))){if(row.optInt("revision")!=old.optInt("revision"))throw new IOException("ルートが更新されています。開き直してください");found=true;}else next.put(old);}if(!found&&row.optInt("revision")!=0)throw new IOException("削除済みのルートです");if(next.length()>=20)throw new IOException("保存は20件までです");row.put("revision",row.optInt("revision")+1);next.put(row);ConversationWorkspace.write(c,STORE,new JSONObject().put("items",next));return row;}
 public static synchronized void remove(Context c,String id,int revision)throws Exception{JSONArray rows=list(c),next=new JSONArray();boolean found=false;for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(id.equals(row.getString("id"))){if(row.optInt("revision")!=revision)throw new IOException("ルートが更新されています");found=true;}else next.put(row);}if(!found)throw new IOException("削除済みです");ConversationWorkspace.write(c,STORE,new JSONObject().put("items",next));}
 public static String summary(JSONObject route){JSONArray legs=route.optJSONArray("legs");StringBuilder s=new StringBuilder(route.optString("name"));if(legs!=null)for(int i=0;i<legs.length();i++){JSONObject l=legs.optJSONObject(i);s.append("\n").append(i+1).append(". ").append(label(l.optString("mode"))).append(" ").append(l.optJSONObject("from").optString("name")).append(" → ").append(l.optJSONObject("to").optString("name")).append(ready(l)?"":"（地点・乗降情報の入力待ち）");}return s.toString();}
 static String norm(String s){return Normalizer.normalize(s,Normalizer.Form.NFKC).replaceAll("[\\s　]","").replace("駅","").replace("停留所","");}
 public static boolean matches(JSONObject route,JSONObject leg){if(!mode(leg).equals("transit")){JSONArray roadLegs=route.optJSONArray("legs");if(roadLegs==null)return false;boolean found=false,bicycle=false;for(int i=0;i<roadLegs.length();i++){JSONArray steps=roadLegs.optJSONObject(i).optJSONArray("steps");if(steps==null)continue;for(int k=0;k<steps.length();k++){String travel=steps.optJSONObject(k).optString("travelMode");if(travel.equals("TRANSIT")||travel.equals("DRIVE"))return false;if(mode(leg).equals("walking")&&!travel.equals("WALK"))return false;if(mode(leg).equals("bicycling")&&!travel.equals("WALK")&&!travel.equals("BICYCLE")&&!travel.equals("BICYCLING"))return false;found=true;if(travel.equals("BICYCLE")||travel.equals("BICYCLING"))bicycle=true;}}return found&&(!mode(leg).equals("bicycling")||bicycle);}JSONArray legs=route.optJSONArray("legs");if(legs==null)return false;String first="",last="";int rides=0;for(int i=0;i<legs.length();i++){JSONArray steps=legs.optJSONObject(i).optJSONArray("steps");if(steps==null)continue;for(int j=0;j<steps.length();j++){JSONObject step=steps.optJSONObject(j);if(!"TRANSIT".equals(step.optString("travelMode")))continue;JSONObject d=step.optJSONObject("transitDetails"),line=d==null?null:d.optJSONObject("transitLine"),v=line==null?null:line.optJSONObject("vehicle"),stops=d==null?null:d.optJSONObject("stopDetails");if(v==null||stops==null)return false;String type=v.optString("type");boolean bus=type.contains("BUS"),rail=type.contains("TRAIN")||type.contains("RAIL")||type.equals("SUBWAY")||type.equals("TRAM");if(leg.optString("mode").equals("bus")?!bus:!rail)return false;String selected=norm(leg.optString("line"));if(!selected.isEmpty()&&!norm(line.optString("name")+line.optString("nameShort")).contains(selected))return false;JSONObject a=stops.optJSONObject("departureStop"),b=stops.optJSONObject("arrivalStop");if(a==null||b==null)return false;if(rides++==0)first=norm(a.optString("name"));last=norm(b.optString("name"));}}
 String board=norm(leg.optString("board")),alight=norm(leg.optString("alight"));return rides>0&&!board.isEmpty()&&!alight.isEmpty()&&first.contains(board)&&last.contains(alight);}
 public static Exception routeFailure(String mode,Exception e){return mode.equals("bicycling")&&"google_route_not_found".equals(e.getMessage())?new IOException("指定した自転車区間の経路がありません。徒歩へ自動変更しません。"):e;}
 public static JSONArray filter(JSONArray routes,JSONObject leg)throws Exception{JSONArray rows=new JSONArray();for(int i=0;i<routes.length();i++)if(matches(routes.getJSONObject(i),leg))rows.put(routes.get(i));if(rows.length()==0)throw new IOException("指定した交通手段・路線・乗降地点に合う候補がありません。別の条件へ自動変更しません。");return rows;}
 private SavedNavigationRoutes(){}
}
